<style>
    .orion-customer-inner,.orion-customer-inner *{box-sizing:border-box;font-family:'Cairo',sans-serif}
    .orion-customer-inner{
        --ci-panel:#0c1728;--ci-panel2:#0f1b2e;--ci-border:#21324d;--ci-soft:#17263c;
        --ci-text:#eef3fb;--ci-muted:#71839e;--ci-purple:#8b5cf6;--ci-green:#34d399;
        --ci-red:#fb7185;--ci-amber:#fbbf24;--ci-blue:#60a5fa;direction:rtl;color:var(--ci-text);width:100%;padding-bottom:24px
    }
    .fi-header{margin-bottom:14px!important}.fi-header-heading{color:#f3f6fb!important;font-weight:950!important}.fi-breadcrumbs{color:#697b96!important}
    .ci-hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:18px;min-height:118px;padding:18px 19px;margin-bottom:13px;border:1px solid var(--ci-border);border-radius:15px;background:radial-gradient(circle at 8% 4%,rgba(139,92,246,.18),transparent 31%),radial-gradient(circle at 92% 110%,rgba(52,211,153,.07),transparent 32%),linear-gradient(145deg,#0e192b,#0a1423);box-shadow:0 18px 45px rgba(0,0,0,.12)}
    .ci-hero-main{display:flex;align-items:center;gap:13px;min-width:0}.ci-avatar,.ci-icon{width:50px;height:50px;border-radius:14px;flex:none;display:grid;place-items:center;color:#c3b2ff;border:1px solid rgba(139,92,246,.38);background:linear-gradient(145deg,rgba(124,58,237,.28),rgba(76,29,149,.12));box-shadow:0 10px 25px rgba(76,29,149,.16)}
    .ci-avatar{font-size:18px;font-weight:950;text-transform:uppercase}.ci-icon svg{width:23px;height:23px}.ci-eyebrow{color:#8e7be8;font-size:8px;font-weight:950;letter-spacing:1.35px;margin-bottom:4px}.ci-title{color:#f5f7fb;font-size:19px;font-weight:950;line-height:1.25}.ci-sub{color:var(--ci-muted);font-size:9px;font-weight:650;margin-top:5px}
    .ci-chips{display:flex;align-items:center;justify-content:flex-end;gap:7px;flex-wrap:wrap}.ci-chip{display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 10px;border:1px solid #263a58;border-radius:9px;background:#0c1829;color:#9aabc0;font-size:8px;font-weight:900;white-space:nowrap}.ci-chip strong{color:#e4eaf3;font-size:9px;direction:ltr}.ci-chip.green{border-color:rgba(52,211,153,.23);background:rgba(52,211,153,.055);color:#6eddb8}.ci-chip.amber{border-color:rgba(251,191,36,.22);background:rgba(251,191,36,.05);color:#f1c85e}.ci-chip.blue{border-color:rgba(96,165,250,.22);background:rgba(96,165,250,.05);color:#79b6ff}.ci-dot{width:6px;height:6px;border-radius:50%;background:currentColor;box-shadow:0 0 9px currentColor}
    .ci-content .fi-section{overflow:hidden!important;border:1px solid var(--ci-border)!important;border-radius:14px!important;background:linear-gradient(145deg,#0c1728,#091421)!important;box-shadow:none!important}.ci-content .fi-section+.fi-section{margin-top:11px!important}.ci-content .fi-section-header{border-bottom:1px solid var(--ci-soft)!important;background:rgba(255,255,255,.012)!important}.ci-content .fi-section-header-heading{color:#e8edf5!important;font-weight:950!important}.ci-content .fi-section-header-description{color:#657792!important;font-size:10px!important}
    .ci-content .fi-input-wrp,.ci-content .fi-select-input{border-color:#263a59!important;background:#0d192b!important;box-shadow:none!important}.ci-content .fi-input,.ci-content textarea{color:#e1e8f2!important}.ci-content .fi-fo-field-wrp-label{color:#9aa9bd!important;font-weight:800!important}.ci-content .fi-fo-field-wrp-helper-text{color:#596c87!important}.ci-content .fi-in-entry{min-height:62px}.ci-content .fi-in-entry-label{color:#667a95!important;font-size:9px!important;font-weight:850!important}.ci-content .fi-in-text{color:#e4eaf3!important;font-weight:750!important}.ci-content .fi-badge{font-weight:850!important}
